/* eslint-disable no-console */
import os from 'os';
import { subprocessEnvironment } from '../utils/subprocessEnvironment';
import path from 'path';
import { RivetChannels, parseRivetChannel } from './channelManager';
import { runNpm } from './npmCommand';
import { errorMessage } from '../utils/errorMessage';

const CHANNEL_USAGE = `Rivet channel QA

Usage:
  yarn rivet:channel install <local|production> [host...|all]
  yarn rivet:channel use <local|production> [host...|all]
  yarn rivet:channel refresh <local|production>
  yarn rivet:channel uninstall <host...|all> [--remove-cli]
  yarn rivet:channel status

Hosts: claude, claude-desktop, cursor, codex, all
`;

const resolveGlobalPrefix = async (): Promise<string> => {
  const result = await runNpm({
    args: ['prefix', '--global'],
    env: subprocessEnvironment('packageManager'),
  });
  if (result.error || result.status !== 0 || !result.stdout.trim()) {
    throw new Error('Could not resolve the global npm prefix');
  }
  return result.stdout.trim();
};

const printStatus = (channels: RivetChannels): void => {
  const status = channels.status();
  console.log(`Selected channel: ${status.selectedChannel ?? 'none'}`);
  console.log(`Active channel: ${status.activeChannel ?? 'none'}`);
  console.log(
    `CLI: ${status.isCliInstalled ? status.activeCliPath : 'not installed'}`,
  );
  console.log(
    `Local: ${status.local.isAvailable ? (status.local.version ?? 'unknown version') : 'not built'} (${status.local.revision ?? 'unknown revision'})`,
  );
  console.log(
    `Production: ${status.production.isAvailable ? (status.production.version ?? 'unknown version') : 'not installed'}`,
  );
};

export const runChannelCli = async (args: string[]): Promise<number> => {
  try {
    const repoRoot = path.resolve(__dirname, '..', '..');
    const channels = new RivetChannels({
      globalPrefix: await resolveGlobalPrefix(),
      homeDirectory: os.homedir(),
      repoRoot,
    });
    const command = args[0];
    if (!command || command === 'help' || command === '--help') {
      console.log(CHANNEL_USAGE);
      return 0;
    }
    if (command === 'status') {
      printStatus(channels);
      return 0;
    }
    if (command === 'refresh') {
      channels.refresh(parseRivetChannel(args[1]));
      printStatus(channels);
      return 0;
    }
    if (command === 'install' || command === 'use') {
      const channel = parseRivetChannel(args[1]);
      const hosts = args.slice(2);
      const selectedHosts = hosts.length > 0 ? hosts : ['all'];
      if (command === 'install') {
        channels.install(channel, selectedHosts);
      } else {
        channels.use(channel, selectedHosts);
      }
      printStatus(channels);
      return 0;
    }
    if (command === 'uninstall') {
      const isCliRemovalRequested = args.includes('--remove-cli');
      const hosts = args.slice(1).filter((arg) => arg !== '--remove-cli');
      if (hosts.length === 0) {
        throw new Error('Uninstall requires at least one host or all');
      }
      channels.uninstall(hosts, isCliRemovalRequested);
      printStatus(channels);
      return 0;
    }
    throw new Error(`Unknown channel command: ${command}`);
  } catch (error) {
    console.error(errorMessage(error));
    console.error(CHANNEL_USAGE);
    return 1;
  }
};

if (require.main === module) {
  void runChannelCli(process.argv.slice(2)).then((exitCode) => {
    process.exitCode = exitCode;
  });
}
